(function(){
"use strict";
function getDevice(){
var nav=navigator,cores=nav.hardwareConcurrency||4,mem=nav.deviceMemory||4;
var mob=/Android|iPhone|iPad|Mobile/i.test(navigator.userAgent);
var s=Math.min(cores,12)+Math.min(mem,8)*1.5+(mob?0:4)+((nav.gpu)?4:0);
var tier=1,label='LOW'; if(s>=24){tier=3;label='ULTRA';}else if(s>=16){tier=2;label='MID';}else if(s<=8){tier=0;label='POTATO';}
var bud=[{p:2500,pr:1},{p:8000,pr:1},{p:20000,pr:1.5},{p:50000,pr:2}][tier];
return{tier:tier,label:label,budget:bud};
}
function boot(opts){
opts=opts||{}; var dev=getDevice();
var cv=typeof opts.canvas==='string'?document.querySelector(opts.canvas):opts.canvas;
if(!cv&&opts.particles!==false){cv=document.createElement('canvas');cv.style.cssText='position:fixed;inset:0;width:100vw;height:100vh;z-index:-1;pointer-events:none';document.body.prepend(cv);}
var count=opts.count||dev.budget.p, ema=16.6, active=count, last=performance.now();
var hud=null;
if(opts.hud){hud=document.createElement('div');hud.style.cssText='position:fixed;left:12px;bottom:12px;z-index:99999;font:12px monospace;background:rgba(0,0,0,.6);color:#22d3ee;padding:6px 10px;border-radius:8px';document.body.appendChild(hud);}
if(!cv){if(hud)hud.textContent='NEXA: no canvas';return{device:dev};}
var gl=cv.getContext('webgl',{antialias:false}); if(!gl)return{device:dev};
var px=new Float32Array(count),py=new Float32Array(count),vx=new Float32Array(count),vy=new Float32Array(count),sz=new Float32Array(count),al=new Float32Array(count),col=new Float32Array(count*3),pos=new Float32Array(count*2);
for(var i=0;i<count;i++){px[i]=Math.random()*2-1;py[i]=Math.random()*2-1;var a=Math.random()*6.28,s=.02+Math.random()*.12;vx[i]=Math.cos(a)*s;vy[i]=Math.sin(a)*s;sz[i]=1+Math.random()*3;al[i]=.25+Math.random()*.75;var t=Math.random();col[i*3]=.3+t*.7;col[i*3+1]=.6+Math.random()*.4;col[i*3+2]=1;}
function sh(tp,src){var o=gl.createShader(tp);gl.shaderSource(o,src);gl.compileShader(o);return o;}
var VS='attribute vec2 a_pos;attribute float a_size;attribute vec3 a_col;attribute float a_alpha;varying vec3 v_col;varying float v_alpha;void main(){v_col=a_col;v_alpha=a_alpha;gl_PointSize=a_size;gl_Position=vec4(a_pos,0.,1.);}';
var FS='precision mediump float;varying vec3 v_col;varying float v_alpha;void main(){vec2 uv=gl_PointCoord-.5;float d=length(uv);if(d>.5)discard;gl_FragColor=vec4(v_col,v_alpha*smoothstep(.5,0.,d));}';
var pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,VS));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,FS));gl.linkProgram(pr);gl.useProgram(pr);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
var bP=gl.createBuffer(),bS=gl.createBuffer(),bC=gl.createBuffer(),bA=gl.createBuffer();
function fit(){var prr=dev.budget.pr;cv.width=Math.floor(innerWidth*prr);cv.height=Math.floor(innerHeight*prr);gl.viewport(0,0,cv.width,cv.height);}fit();addEventListener('resize',fit,{passive:true});
var mx=999,my=999;addEventListener('pointermove',function(e){var r=cv.getBoundingClientRect();mx=((e.clientX-r.left)/r.width)*2-1;my=-(((e.clientY-r.top)/r.height)*2-1);},{passive:true});
function bind(b,loc,size,data){var l=gl.getAttribLocation(pr,loc);gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);gl.enableVertexAttribArray(l);gl.vertexAttribPointer(l,size,gl.FLOAT,false,0,0);}
function loop(t){requestAnimationFrame(loop);var dtms=Math.min(t-last,100);last=t;ema=ema*.95+dtms*.05;
active=count; if(ema>20)active=Math.floor(count*.4);else if(ema>17)active=Math.floor(count*.7);
var dt=Math.min(dtms/1000,.05),damp=1-Math.min(dt*.6,.05);
for(var k=0;k<active;k++){var dx=px[k]-mx,dy=py[k]-my,d2=dx*dx+dy*dy;if(d2<.02&&d2>.00001){var f=(.02-d2)*8*dt/Math.sqrt(d2);vx[k]+=dx*f;vy[k]+=dy*f;}px[k]+=vx[k]*dt;py[k]+=vy[k]*dt;vx[k]*=damp;vy[k]*=damp;if(px[k]>1)px[k]=-1;else if(px[k]<-1)px[k]=1;if(py[k]>1)py[k]=-1;else if(py[k]<-1)py[k]=1;pos[k*2]=px[k];pos[k*2+1]=py[k];}
gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.useProgram(pr);
bind(bP,'a_pos',2,pos.subarray(0,active*2));bind(bS,'a_size',1,sz.subarray(0,active));bind(bC,'a_col',3,col.subarray(0,active*3));bind(bA,'a_alpha',1,al.subarray(0,active));
gl.drawArrays(gl.POINTS,0,active);
if(hud)hud.textContent=(1000/Math.max(ema,.01)).toFixed(0)+' FPS · '+dev.label+' · '+(active/1000).toFixed(1)+'k NEXA';
}requestAnimationFrame(loop);
console.log('%c⚡ NEXA Core v1.0-lite CDN — '+dev.label,'color:#22d3ee;font-weight:bold');
return{device:dev};
}
window.Nexa={boot:boot,version:'1.0.0-lite'};
if(document.currentScript&&document.currentScript.hasAttribute('data-auto')){
var s=document.currentScript;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){boot({particles:true,hud:true,count:parseInt(s.getAttribute('data-particles')||'0')||undefined});});
else boot({particles:true,hud:true});
}
})();
